html:
{#- ================================================================
    NLSIU — Applicant Application Form — Print Format  v7
    KEY FIX: Frappe wraps print formats in its own letterhead/body
    container that adds padding. We override ALL of that with aggressive
    negative-margin / full-bleed CSS so the pf-page fills the A4 sheet
    edge-to-edge, then we add a uniform 6px inner padding inside the
    content table. The visible border stays; white gaps are gone.
    ================================================================ -#}

{%- set _site = frappe.utils.get_url() -%}

{%- macro f(v) -%}{%- if v and v != 'None' -%}{{ v }}{%- else -%}&mdash;{%- endif -%}{%- endmacro -%}
{%- macro fd(v) -%}{%- if v -%}{{ frappe.utils.formatdate(v,'dd-MM-yyyy') }}{%- else -%}&mdash;{%- endif -%}{%- endmacro -%}

{%- set is_phd        = (doc.program_level or '') | lower in ['phd', 'research course'] -%}
{%- set show_guardian = doc.guardian_required -%}
{%- set _ews_val      = (doc.ews or '') | lower -%}
{%- set _pwd_val      = (doc.pwd or '') | lower -%}
{%- set _ka_any       = doc.ka_study_7yrs or doc.ka_defence_child or doc.ka_govt_child or doc.ka_ais_child or doc.ka_capf_child -%}

{#- Smart address builder -#}
{%- set _addr_parts = [] -%}
{%- if doc.correspondence_address and doc.correspondence_address not in ['None',''] -%}{%- set _ = _addr_parts.append(doc.correspondence_address) -%}{%- endif -%}
{%- if doc.city and doc.city not in ['None',''] -%}{%- set _ = _addr_parts.append(doc.city) -%}{%- endif -%}
{%- if doc.state and doc.state not in ['None',''] -%}{%- set _ = _addr_parts.append(doc.state) -%}{%- endif -%}
{%- set _addr_str = _addr_parts | join(', ') -%}
{%- if doc.pincode and doc.pincode not in ['None',''] -%}
  {%- set _addr_str = _addr_str ~ (' \u2013 ' if _addr_str else '') ~ doc.pincode -%}
{%- endif -%}

<style>
/* ══════════════════════════════════════════════════════════════
   FRAPPE OVERRIDE — strip every wrapper container's padding so
   our page div sits flush against the A4 @page margin box.
   Frappe v14/v15 injects: #page-body, .print-format-gutter,
   .print-format, .page-break, div[style*="padding"] wrappers.
   We nuke them all.
   ══════════════════════════════════════════════════════════════ */
@page {
  size: A4 portrait;
  margin: 8mm;           /* uniform 8 mm on all 4 sides = ~23px */
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* Frappe body / wrapper resets */
html,
body,
#page-body,
.print-format-gutter,
.print-format,
.page-break,
.letter-head,
.letter-head-content,
form[data-doctype],
.layout-main,
.layout-main-section,
.frappe-card {
  margin:  0 !important;
  padding: 0 !important;
  border:  none !important;
  background: transparent !important;
  width: auto !important;
  max-width: none !important;
}

html, body {
  font-family: Arial, Helvetica, sans-serif;
  font-size: 7pt;
  color: #111;
  background: #fff;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

/* – Page wrapper — fills A4 content area exactly ─────────────
   A4 = 210mm × 297mm. @page margin 8mm each side →
   content box = 194mm × 281mm.
   We let the wrapper BE that content box with no extra margin.
   The 1.5px border is purely decorative (print). */
.pf-page,
.pf-doc-page {
  width: 194mm;
  max-width: 194mm;
  min-height: 281mm;
  margin: 0;
  padding: 0;
  background: #fff;
  border: 1.5px solid #7b1a1a;
  overflow: hidden;
  /* wkhtmltopdf needs this to avoid injecting extra space */
  display: block;
}

/* Screen-only: add visual separation between pages */
@media screen {
  html, body {
    background: #909090;
    padding: 0;
  }
  .pf-page,
  .pf-doc-page {
    box-shadow: 0 3px 18px rgba(0,0,0,.35);
    margin: 12px auto !important;
  }
}

@media print {
  html, body {
    width: 194mm;
    max-width: 194mm;
    margin: 0;
    padding: 0;
    background: #fff;
  }
  .pf-page,
  .pf-doc-page {
    width: 194mm;
    max-width: 194mm;
    margin: 0 !important;
    padding: 0 !important;
    border: 1.5px solid #7b1a1a;
    page-break-after: always;
    overflow: hidden;
  }
  .pf-page:last-child,
  .pf-doc-page:last-child {
    page-break-after: auto;
  }
  .no-print { display: none !important; }
  tr { page-break-inside: avoid; }
  .deg-table tr { page-break-inside: avoid; }
}

/* – Header ────────────────────────────
   Flush to top of wrapper, no rounding, exact dark red.        */
.pf-header {
  background: #7b1a1a;
  color: #fff;
  display: flex;
  align-items: center;
  padding: 5px 8px;
  gap: 8px;
  border-radius: 0;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}
.pf-logo {
  width: 36px; height: 36px; flex-shrink: 0;
  background: #fff; border-radius: 2px;
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
.pf-logo img  { width: 32px; height: 32px; object-fit: contain; }
.pf-logo-text { font-size: 5.5pt; color: #7b1a1a; font-weight: bold; text-align: center; line-height: 1.2; }
.pf-hdr-body  { flex: 1; text-align: center; }
.pf-hdr-inst  { font-size: 10pt; font-weight: bold; text-transform: uppercase; letter-spacing: .5px; line-height: 1.2; color: #fff; }
.pf-hdr-sub   { font-size: 5.5pt; letter-spacing: 1px; text-transform: uppercase; margin-top: 1px; color: #ffcccc; }

/* – Title bar ────────────────────────────────────────────────── */
.pf-title-bar {
  text-align: center;
  padding: 3px 6px;
  background: #fff;
  border-bottom: 1px solid #ddd;
}
.pf-title    { font-size: 8.5pt; font-weight: bold; color: #111; }
.pf-subtitle { font-size: 6.5pt; color: #555; margin-top: 1px; }
.sep         { margin: 0 3px; color: #bbb; }

/* – Main table ──────────────────────────────────
   5-col fixed-layout. No outer table border — the .pf-page
   border provides the outer frame.                              */
.pf-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.pf-table td {
  border: 1px solid #d0d0d0;
  padding: 2px 5px;
  vertical-align: middle;
  font-size: 6.8pt;
  line-height: 1.35;
  word-wrap: break-word;
  overflow-wrap: break-word;
}

/* Section header row */
.pf-sec {
  background: #7b1a1a !important;
  color: #fff !important;
  font-weight: bold;
  font-size: 7pt;
  letter-spacing: .25px;
  text-transform: uppercase;
  padding: 2px 8px;
  border: none !important;
  border-top: 1px solid #5a0e0e !important;
  border-bottom: 1px solid #5a0e0e !important;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}
/* Sub-section header row */
.pf-subsec {
  background: #f4e4e4 !important;
  color: #7b1a1a !important;
  font-weight: bold;
  font-size: 6.8pt;
  padding: 1px 8px;
  border-color: #ccc !important;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

/* Label / Value cells */
.pf-lbl { font-weight: normal; color: #444; background: #f9f6f6; }
.pf-val { color: #111; background: #fff; }

/* – Photo cell ─────────────────────────────────── */
.pf-photo {
  width: 27mm !important;
  max-width: 27mm !important;
  text-align: center;
  vertical-align: top;
  padding: 3px;
  background: #fff;
  border: 1px solid #d0d0d0 !important;
}
.pf-photo img {
  width: 23mm;
  height: 30mm;
  object-fit: cover;
  display: block;
  margin: 0 auto 2px;
  border: 1px solid #ccc;
}
.pf-photo-cap {
  font-size: 5.5pt; color: #888; text-align: center; line-height: 1.3;
}
.pf-photo-empty {
  width: 23mm; height: 30mm;
  background: #f2f2f2;
  border: 1px dashed #bbb;
  display: flex; align-items: center; justify-content: center;
  font-size: 5.5pt; color: #aaa; text-align: center; margin: 0 auto 2px;
}

/* – Status badges ────────────────────────────────── */
.badge-green  { background:#276726; color:#fff; font-weight:bold; padding:1px 5px; border-radius:2px; font-size:6.2pt; display:inline-flex; align-items:center; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
.badge-yellow { background:#a34d00; color:#fff; font-weight:bold; padding:1px 5px; border-radius:2px; font-size:6.2pt; display:inline-flex; align-items:center; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
.badge-red    { background:#a81616; color:#fff; font-weight:bold; padding:1px 5px; border-radius:2px; font-size:6.2pt; display:inline-flex; align-items:center; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
.badge-grey   { background:#3d3d3d; color:#fff; font-weight:bold; padding:1px 5px; border-radius:2px; font-size:6.2pt; display:inline-flex; align-items:center; -webkit-print-color-adjust:exact; print-color-adjust:exact; }

/* – Degree inner table ───────────────────────────── */
.deg-table { width:100%; border-collapse:collapse; font-size:6.5pt; }
.deg-table th { background:#f4e4e4 !important; color:#7b1a1a; font-weight:bold; padding:1px 5px; border:1px solid #ccc; text-align:left; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
.deg-table td { padding:1px 5px; border:1px solid #ccc; vertical-align:middle; }
.deg-table tr:nth-child(even) td { background:#fafafa; }

/* – Declaration ────────────────────────────────── */
.pf-decl { padding:3px 8px; font-size:6.5pt; line-height:1.45; color:#111; background:#fff; border-top:1px solid #ddd; }
.pf-decl-item { display:flex; align-items:flex-start; gap:4px; margin-bottom:2px; }
.pf-decl-item:last-child { margin-bottom:0; }
.pf-chk  { font-size:9pt; line-height:1; flex-shrink:0; margin-top:0px; }
.pf-decl-text { flex:1; }

/* – Invigilator note ─────────────────────────────── */
.pf-invig { text-align:center; font-size:6pt; font-style:italic; color:#666; padding:2px 8px; background:#f9f9f9; border-top:1px solid #ddd; }

/* – Signature table ─────────────────────────────── */
.pf-sig-table { width:100%; border-collapse:collapse; border-top:1px solid #ddd; }
.pf-sig-table td { border:1px solid #d0d0d0; padding:2px 10px 12px; text-align:center; font-size:6.5pt; vertical-align:bottom; width:50%; }
.pf-sig-head  { font-weight:bold; font-size:6.5pt; background:#f9f9f9; }
.pf-sig-space { height:26px; display:block; }

/* – Footer ────────────────────────────────────── */
.pf-footer {
  border-top:1px dashed #ccc;
  text-align:center;
  font-size:5.8pt;
  color:#888;
  padding:2px 6px;
  background:#fff;
}

/* – Document page body ───────────────────────────
.pf-doc-body  { padding: 5mm 6mm; }
.pf-doc-label { font-weight:bold; font-size:6.8pt; color:#fff; background:#7b1a1a; padding:2px 7px; margin-bottom:2px; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
.pf-doc-image { text-align:center; border:1px solid #ccc; padding:3px; }
.pf-doc-image img { max-width:100%; max-height:160mm; }
.pf-doc-pdf   { padding:8px; background:#fafafa; border:1px solid #ccc; text-align:center; color:#555; font-size:6.8pt; }
</style>



<div class="pf-page">

  <div class="pf-header">
    <div class="pf-logo">
      {%- set _logo = frappe.db.get_single_value('Institution Settings','logo') -%}
      {%- if _logo -%}<img src="{{ _site }}{{ _logo }}" alt="NLSIU">
      {%- else -%}<span class="pf-logo-text">NLSIU</span>{%- endif -%}
    </div>
    <div class="pf-hdr-body">
      <div class="pf-hdr-inst">National Law School of India University</div>
      <div class="pf-hdr-sub">Bengaluru &nbsp;·&nbsp; Office of Admissions &nbsp;·&nbsp; Examination Cell</div>
    </div>
  </div>

  <div class="pf-title-bar">
    <div class="pf-title">Application Form{%- if doc.program %} &mdash; {{ doc.program }}{%- endif -%}</div>
    <div class="pf-subtitle">
      Admission to {{ doc.program or '' }}
      {%- if doc.academic_year -%}<span class="sep">|</span>{{ doc.academic_year }}{%- endif -%}
      {%- if doc.name -%}<span class="sep">|</span>{{ doc.name }}{%- endif -%}
    </div>
  </div>


  <table class="pf-table">
    <colgroup>
      <col style="width:22%">
      <col style="width:26%">
      <col style="width:22%">
      <col><!-- auto -->
      <col style="width:27mm">
    </colgroup>


    <tr><td colspan="5" class="pf-sec">1. Personal Information</td></tr>

    <tr>
      <td class="pf-lbl">Application ID</td>
      <td class="pf-val">{{ doc.name }}</td>
      <td class="pf-lbl">Status</td>
      {%- set _st = doc.application_status or 'Draft' -%}
      <td class="pf-val">
        {%- if _st in ['Approved','Admitted','Allocated','Verified'] -%}<span class="badge-green">{{ _st }}</span>
        {%- elif _st in ['Pending','Under Review','Submitted'] -%}<span class="badge-yellow">{{ _st }}</span>
        {%- elif _st in ['Rejected','Cancelled'] -%}<span class="badge-red">{{ _st }}</span>
        {%- else -%}<span class="badge-grey">{{ _st }}</span>{%- endif -%}
      </td>
      <td class="pf-photo" rowspan="9">
        {%- if doc.candidate_photo -%}
          <img src="{{ _site }}{{ doc.candidate_photo }}" alt="Photo">
        {%- else -%}
          <div class="pf-photo-empty">Photo<br>Not<br>Uploaded</div>
        {%- endif -%}
        <div class="pf-photo-cap">Candidate's<br>Photograph</div>
      </td>
    </tr>

    <tr>
      <td class="pf-lbl">Candidate's Name</td>
      <td class="pf-val" colspan="3">
        {%- if doc.title and doc.title not in ['None',''] -%}{{ doc.title }}&nbsp;{%- endif -%}{{ f(doc.candidate_name) }}
      </td>
    </tr>
    <tr>
      <td class="pf-lbl">Date of Birth</td>
      <td class="pf-val" colspan="3">{{ fd(doc.date_of_birth) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Gender</td>
      <td class="pf-val" colspan="3">{{ f(doc.gender) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Nationality</td>
      <td class="pf-val">{{ f(doc.nationality) }}</td>
      <td class="pf-lbl">Religion</td>
      <td class="pf-val">{{ f(doc.religion) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Mobile Number</td>
      <td class="pf-val">{{ f(doc.mobile_number) }}</td>
      <td class="pf-lbl">Alternate Contact</td>
      <td class="pf-val">{{ f(doc.alternate_contact) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Email Address</td>
      <td class="pf-val" colspan="3">{{ f(doc.email) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Programme Applied</td>
      <td class="pf-val">{{ f(doc.program) }}</td>
      <td class="pf-lbl">Academic Year</td>
      <td class="pf-val">{{ f(doc.academic_year) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Annual Household Income</td>
      <td class="pf-val" colspan="3">{{ f(doc.annual_house_hold_income) }}</td>
    </tr>


    <tr>
      <td class="pf-lbl">Correspondence Address</td>
      <td class="pf-val" colspan="4">
        {%- if _addr_str -%}{{ _addr_str }}{%- else -%}&mdash;{%- endif -%}
      </td>
    </tr>


    <tr><td colspan="5" class="pf-sec">2. Family Information</td></tr>

    {%- if show_guardian -%}
    <tr>
      <td class="pf-lbl">Guardian's Name</td>
      <td class="pf-val">{{ f(doc.guardian_name) }}</td>
      <td class="pf-lbl">Guardian's Mobile</td>
      <td class="pf-val" colspan="2">{{ f(doc.guardian_mobile) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Guardian's Email</td>
      <td class="pf-val" colspan="4">{{ f(doc.guardian_email) }}</td>
    </tr>
    {%- else -%}
    <tr>
      <td class="pf-lbl">Father's Name</td>
      <td class="pf-val">{{ f(doc.father_name) }}</td>
      <td class="pf-lbl">Father's Occupation</td>
      <td class="pf-val" colspan="2">{{ f(doc.father_occupation) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Father's Mobile</td>
      <td class="pf-val">{{ f(doc.father_mobile) }}</td>
      <td class="pf-lbl">Father's Email</td>
      <td class="pf-val" colspan="2">{{ f(doc.father_email) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Mother's Name</td>
      <td class="pf-val">{{ f(doc.mother_name) }}</td>
      <td class="pf-lbl">Mother's Occupation</td>
      <td class="pf-val" colspan="2">{{ f(doc.mother_occupation) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Mother's Mobile</td>
      <td class="pf-val">{{ f(doc.mother_mobile) }}</td>
      <td class="pf-lbl">Mother's Email</td>
      <td class="pf-val" colspan="2">{{ f(doc.mother_email) }}</td>
    </tr>
    {%- endif -%}


    <tr><td colspan="5" class="pf-sec">3. Academic Details</td></tr>

    <tr><td colspan="5" class="pf-subsec">Class X &mdash; Secondary School</td></tr>
    <tr>
      <td class="pf-lbl">School Name</td>
      <td class="pf-val" colspan="4">{{ f(doc.class_x_school) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Board</td>
      <td class="pf-val">{{ f(doc.class_x_board) }}</td>
      <td class="pf-lbl">Year of Completion</td>
      <td class="pf-val" colspan="2">{{ f(doc.class_x_year_of_completion) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Percentage (%)</td>
      <td class="pf-val">{{ f(doc.class_x_percentage) }}</td>
      <td class="pf-lbl">If CGPA</td>
      <td class="pf-val" colspan="2">{{ f(doc.class_x_cgpa) }}</td>
    </tr>

    <tr><td colspan="5" class="pf-subsec">Class XII &mdash; Higher Secondary</td></tr>
    <tr>
      <td class="pf-lbl">Examination Name</td>
      <td class="pf-val" colspan="4">{{ f(doc.class_xii_name_of_examination) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">School / College</td>
      <td class="pf-val" colspan="4">{{ f(doc.class_xii_school) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Board</td>
      <td class="pf-val">{{ f(doc.class_xii_board) }}</td>
      <td class="pf-lbl">Year of Completion</td>
      <td class="pf-val" colspan="2">{{ f(doc.class_xii_year_of_completion) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Percentage (%)</td>
      <td class="pf-val">{{ f(doc.class_xii_percentage) }}</td>
      <td class="pf-lbl">If CGPA</td>
      <td class="pf-val" colspan="2">{{ f(doc.class_xii_cgpa) }}</td>
    </tr>
    {%- if doc.hsc_group or doc.hsc_percentage -%}
    <tr>
      <td class="pf-lbl">HSC Group / Stream</td>
      <td class="pf-val">{{ f(doc.hsc_group) }}</td>
      <td class="pf-lbl">HSC Percentage</td>
      <td class="pf-val" colspan="2">{{ f(doc.hsc_percentage) }}</td>
    </tr>
    {%- endif -%}

    {%- if doc.national_test_name or doc.percentage -%}
    <tr><td colspan="5" class="pf-subsec">National / Entrance Test</td></tr>
    <tr>
      <td class="pf-lbl">Test Name</td>
      <td class="pf-val">{{ f(doc.national_test_name) }}</td>
      <td class="pf-lbl">Score / Percentile</td>
      <td class="pf-val" colspan="2">{{ f(doc.percentage) }}</td>
    </tr>
    {%- endif -%}

    {%- if not is_phd and doc.ug_degree_details -%}
    <tr><td colspan="5" class="pf-subsec">Undergraduate Degree(s)</td></tr>
    <tr>
      <td colspan="5" style="padding:3px 5px;">
        <table class="deg-table">
          <tr><th style="width:30%">Programme</th><th style="width:40%">College / University</th><th style="width:15">Year</th><th style="width:15%">% / CGPA</th></tr>
          {%- for d in doc.ug_degree_details -%}
          <tr><td>{{ f(d.ug_program) }}</td><td>{{ f(d.college) }}</td><td>{{ f(d.year_of_completion) }}</td><td>{{ f(d.ug_cgpa or d.percentage_cgpa_obtained) }}</td></tr>
          {%- else -%}
          <tr><td colspan="4" style="color:#999;text-align:center;">&mdash;</td></tr>
          {%- endfor -%}
        </table>
      </td>
    </tr>
    {%- if doc.ug_degree_completion -%}
    <tr>
      <td class="pf-lbl">UG Completion Status</td>
      <td class="pf-val" colspan="4">{{ f(doc.ug_degree_completion) }}</td>
    </tr>
    {%- endif -%}
    {%- endif -%}

    {%- if is_phd -%}
    <tr><td colspan="5" class="pf-subsec">Undergraduate Degree(s)</td></tr>
    <tr>
      <td colspan="5" style="padding:3px 5px;">
        <table class="deg-table">
          <tr><th style="width:30%">Programme</th><th style="width:40%">College / University</th><th style="width:15">Year</th><th style="width:15%">% / CGPA</th></tr>
          {%- for d in (doc.ug_degree_details or []) -%}
          <tr><td>{{ f(d.ug_program) }}</td><td>{{ f(d.college) }}</td><td>{{ f(d.year_of_completion) }}</td><td>{{ f(d.ug_cgpa or d.percentage_cgpa_obtained) }}</td></tr>
          {%- else -%}<tr><td colspan="4" style="color:#999;text-align:center;">&mdash;</td></tr>{%- endfor -%}
        </table>
      </td>
    </tr>
    <tr><td colspan="5" class="pf-subsec">Postgraduate Degree(s)</td></tr>
    <tr>
      <td colspan="5" style="padding:3px 5px;">
        <table class="deg-table">
