    <tr><td colspan="5" class="pf-subsec">Karnataka Category</td></tr>
    {%- if doc.ka_study_7yrs -%}
    <tr>
      <td class="pf-lbl">Studied in Karnataka (7 yrs)</td><td class="pf-val">Yes</td>
      <td class="pf-lbl">Certificate</td>
      <td class="pf-val" colspan="2">{% if doc.ka_study_7yrs_certificate %}Uploaded{% else %}&mdash;{% endif %}</td>
